package com.motionstudio.part2
import kotlin.math.*
data class Transform2D(val x:Float=0f,val y:Float=0f,val scaleX:Float=1f,val scaleY:Float=1f,val rotation:Float=0f,val anchorX:Float=0f,val anchorY:Float=0f,val skewX:Float=0f,val skewY:Float=0f,val cropLeft:Int=0,val cropTop:Int=0,val cropRight:Int=0,val cropBottom:Int=0,val flipX:Boolean=false,val flipY:Boolean=false)
object TransformRenderer { fun render(src:FrameBuffer,t:Transform2D,outW:Int=src.width,outH:Int=src.height):FrameBuffer{require(outW>0&&outH>0&&t.scaleX!=0f&&t.scaleY!=0f);val o=FrameBuffer(outW,outH);val rad=-t.rotation*PI.toFloat()/180f;val cs=cos(rad);val sn=sin(rad);for(y in 0 until outH)for(x in 0 until outW){var dx=x-t.x-t.anchorX;var dy=y-t.y-t.anchorY;if(t.flipX)dx=-dx;if(t.flipY)dy=-dy;dx-=dy*t.skewX;dy-=dx*t.skewY;val ux=(dx*cs-dy*sn)/t.scaleX+t.anchorX;val uy=(dx*sn+dy*cs)/t.scaleY+t.anchorY;if(ux>=t.cropLeft&&uy>=t.cropTop&&ux<src.width-t.cropRight&&uy<src.height-t.cropBottom)o.set(x,y,src.bilinear(ux,uy))};return o}}
